/* @autogenerated */
import { ImportRow, ImportSheet } from './entity-import.model';

/** Formatos que admite el lector. */
export const IMPORT_ACCEPT = '.xlsx,.xls,.ods,.csv';

/**
 * Lee las hojas de un libro (xlsx, xls, ods o csv). La primera fila no vacía de cada hoja son las cabeceras;
 * las filas sin ningún valor se descartan. Cada fila conserva su número en la hoja para el resumen.
 * La librería se carga al leer el primer fichero.
 */
export async function readWorkbook(file: File): Promise<ImportSheet[]> {
  const XLSX = await import('xlsx');
  const book = XLSX.read(await file.arrayBuffer(), { cellDates: true, dense: true });
  return book.SheetNames.map((name) => {
    const sheet = book.Sheets[name];
    const first = sheet['!ref'] ? XLSX.utils.decode_range(sheet['!ref']).s.r : 0;
    const all = XLSX.utils.sheet_to_json<unknown[]>(sheet, { header: 1, raw: true, defval: null, blankrows: true });
    const rows: ImportRow[] = all
      .map((cells, index) => ({ row: first + index + 1, cells }))
      .filter(({ cells }) => cells.some((cell) => cell !== null && String(cell).trim() !== ''));
    const headers = (rows.shift()?.cells ?? []).map((cell) => (cell === null ? '' : String(cell).trim()));
    return { name, headers, rows };
  });
}
